<?php declare(strict_types=1); namespace App\Services\Admin; use App\Models\User; use App\Models\WorkflowTaskDefinition; use App\Models\WorkflowTemplate; use App\Models\WorkflowTransition; use App\Repositories\WorkflowTemplateRepository; use App\Services\Audit\AuditLogger; use Illuminate\Pagination\LengthAwarePaginator; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException; final class WorkflowTemplateAdminService { public function __construct(private WorkflowTemplateRepository $repo,private AuditLogger $audit){} public function paginate(array $f=[],int $per=15): LengthAwarePaginator { return $this->repo->paginateForAdmin($f,$per);} public function findOrFail(int $id,array $rel=[]): WorkflowTemplate { return $this->repo->findOneOrFail($id,$rel?:['definitions.department','transitions']); } public function updateDraft(WorkflowTemplate $t,array $d,User $u): WorkflowTemplate { if($t->published_at) throw ValidationException::withMessages(['template'=>['Draft only']]); return DB::transaction(function()use($t,$d){ if(isset($d['name_en'],$d['name_ar'])) $t->update(['name_en'=>$d['name_en'],'name_ar'=>$d['name_ar']]); foreach($d['definitions']??[] as $def){ WorkflowTaskDefinition::where('template_id',$t->id)->whereKey($def['id'])->firstOrFail()->update(collect($def)->only(['title_en','title_ar','instructions_en','instructions_ar','sla_minutes','escalate_after_minutes','priority'])->all()); } return $t->fresh(['definitions.department','transitions']); }); } public function createDraftFromPublished(WorkflowTemplate $t,User $u): WorkflowTemplate { if(!$t->published_at) throw ValidationException::withMessages(['template'=>['Published only']]); if($d=$this->repo->findDraftByCode($t->code)) return $d->load(['definitions.department','transitions']); return DB::transaction(function()use($t){ $draft=WorkflowTemplate::create(['code'=>$t->code,'version'=>$t->version+1,'name_en'=>$t->name_en,'name_ar'=>$t->name_ar,'scope'=>$t->scope,'is_active'=>false,'published_at'=>null]); $map=[]; foreach($t->definitions as $def){ $map[$def->id]=WorkflowTaskDefinition::create([...$def->only(['code','title_en','title_ar','instructions_en','instructions_ar','department_id','is_entry_point','sla_minutes','escalate_after_minutes','priority','requires_timer','required_fields','required_attachment_types','form_schema','blocks_when_site_not_ready','auto_complete_rule']),'template_id'=>$draft->id])->id; } foreach($t->transitions as $tr){ WorkflowTransition::create(['template_id'=>$draft->id,'from_task_definition_id'=>$map[$tr->from_task_definition_id],'to_task_definition_id'=>$map[$tr->to_task_definition_id],'condition'=>$tr->condition,'join_mode'=>$tr->join_mode,'sort_order'=>$tr->sort_order]); } return $draft->load(['definitions.department','transitions']); }); } public function publish(WorkflowTemplate $t,User $u): WorkflowTemplate { if($t->published_at) throw ValidationException::withMessages(['template'=>['Draft only']]); return DB::transaction(function()use($t,$u){ WorkflowTemplate::where('code',$t->code)->where('id','!=',$t->id)->update(['is_active'=>false]); $t->update(['is_active'=>true,'published_at'=>now()]); $this->audit->log($t,'updated',$u,null,['version'=>$t->version]); return $t->fresh(['definitions.department','transitions']); }); }}